// ../flow-tool/src/services/binding-service.ts
var listBindingsInFlow = async (filePath) => {
  const { workflow } = await readFlowWorkflow(filePath);
  const rawBindings = workflow.bindings ?? [];
  const bindings = rawBindings.map((b) => ({
    id: b.id,
    name: b.name,
    type: b.type,
    resource: b.resource,
    resourceKey: b.resourceKey,
    default: b.default,
    propertyAttribute: b.propertyAttribute,
    resourceSubType: b.resourceSubType
  }));
  return { bindings, count: bindings.length };
};
var addBindingToFlow = async (filePath, name, resource, defaultValue, options = {}) => {
  if (!VALID_RESOURCE_TYPES.includes(resource)) {
    throw new Error(`Invalid resource type: "${resource}". Valid resource types: ${VALID_RESOURCE_TYPES.join(", ")}`);
  }
  const { workflow, refMap } = await readFlowWorkflow(filePath);
  const binding = createBinding({
    name,
    value: defaultValue,
    resource,
    resourceKey: options.resourceKey,
    propertyAttribute: options.propertyAttribute,
    resourceSubType: options.resourceSubType
  });
  addBinding(workflow, binding);
  await writeFlowWorkflow(filePath, workflow, refMap);
  const persisted = workflow.bindings.find((b) => b.name === binding.name && b.resource === binding.resource && b.resourceKey === binding.resourceKey && b.propertyAttribute === binding.propertyAttribute);
  const result = persisted ?? binding;
  return {
    binding: {
      id: result.id,
      name: result.name,
      type: result.type,
      resource: result.resource,
      resourceKey: result.resourceKey,
      default: result.default,
      propertyAttribute: result.propertyAttribute,
      resourceSubType: result.resourceSubType
    }
  };
};
var deleteBindingFromFlow = async (filePath, resourceKey) => {
  const { workflow, refMap } = await readFlowWorkflow(filePath);
  const bindings = workflow.bindings ?? [];
  const matching = bindings.filter((b) => b.resourceKey === resourceKey);
  if (matching.length === 0) {
    const available = [...new Set(bindings.map((b) => b.resourceKey))].join(", ") || "(none)";
    throw new Error(`No bindings found with resourceKey "${resourceKey}". Available resourceKeys: ${available}`);
  }
  const nodes = workflow.nodes ?? [];
  const definitions = workflow.definitions ?? [];
  const referencingNodeIds = [];
  for (const node of nodes) {
    const refs = collectNodeBindingResourceKeys(node, bindings, definitions);
    if (refs.has(resourceKey)) {
      referencingNodeIds.push(node.id);
    }
  }
  if (referencingNodeIds.length > 0) {
    throw new Error(`Cannot delete bindings with resourceKey "${resourceKey}": still referenced by nodes: ${referencingNodeIds.join(", ")}`);
  }
  workflow.bindings = bindings.filter((b) => b.resourceKey !== resourceKey);
  await writeFlowWorkflow(filePath, workflow, refMap);
  const deletedBindings = matching.map((b) => ({
    id: b.id,
    name: b.name,
    type: b.type,
    resource: b.resource,
    resourceKey: b.resourceKey,
    default: b.default,
    propertyAttribute: b.propertyAttribute,
    resourceSubType: b.resourceSubType
  }));
  return { deletedBindings, count: deletedBindings.length };
};
export {
  VALID_RESOURCE_TYPES,
  addBindingToFlow,
  deleteBindingFromFlow,
  listBindingsInFlow
};

